const e=$json||{};
if(e.version!==1||String(e.type)!=='viryaos.team.assignment_email_requested') throw new Error('Unsupported VIRYA team email event');
const d=e.data||{}; const clean=v=>String(v??'').replace(/[\r\n\t]+/g,' ').trim();
const action_id=clean(d.action_id); const assignment_id=clean(d.assignment_id); const to=clean(d.recipient_email).toLowerCase();
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)||!action_id||!assignment_id) throw new Error('Invalid VIRYA team email payload');
const reminder=Math.max(0,Math.min(12,Number(d.reminder_number||0)||0));
const title=clean(d.task_title).slice(0,180)||'Zadanie w VIRYA OS'; const detail=String(d.task_detail||'').trim().slice(0,1800);
const rawName=clean(d.recipient_name); const name=/^Team Member \d+$/i.test(rawName)?'':rawName.split(/\s+/)[0];
let deadline=''; if(d.due_at){ const dt=new Date(d.due_at); if(!Number.isNaN(dt.getTime())) deadline=dt.toLocaleString('pl-PL',{timeZone:'Europe/Warsaw',dateStyle:'medium',timeStyle:'short'}); }
const path=String(d.action_url_path||'/staff/control/'); if(!path.startsWith('/')||path.includes('://')) throw new Error('Invalid action path');
const link='https://virya.music'+path; const hi=name?`Cześć ${name}!`:'Cześć!';
const subject=reminder>0?`VIRYA — przypomnienie: ${title}`:`VIRYA — nowe zadanie: ${title}`;
const lead=reminder>0?'Małe przypomnienie — to zadanie nadal czeka na domknięcie.':'Wpadło do Ciebie nowe zadanie od VIRYA OS.';
const due=deadline?`\nTermin: ${deadline}`:'';
const body=`${hi}\n\n${lead}\n\n${title}\n${detail}${due}\n\nSzczegóły / domknięcie:\n${link}\n\nJeśli coś blokuje wykonanie, po prostu daj znać ekipie — bez spiny.\n\nVIRYA`;
return [{json:{event_id:String(e.id||''),action_id,assignment_id,SendTo:to,SendSubject:subject.slice(0,180),SendBody:body,reminder_number:reminder}}];

const src=$('Validate and build friendly team email').item.json||{}; const r=$json||{};
const disposition=String(r.disposition||'');
if(disposition==='already_succeeded') return [];
if(disposition!=='claimed'||!r.claim_token) throw new Error(`VIRYA team email execution is ${disposition||'unclaimed'}; fail closed to avoid duplicate provider side effects`);
return [{json:{...src,claim_token:String(r.claim_token),attempt_number:Number(r.attempt_number||1)}}];

const src=$('Resolve execution claim').item.json||{}; const sent=$('Gmail — send team task').item.json||{};
const provider=String(sent.threadId||sent.thread_id||sent.id||sent.messageId||'').trim(); if(!provider) throw new Error('Gmail success missing provider reference');
return [{json:{action_id:src.action_id,claim_token:src.claim_token,status:'succeeded',provider_reference:provider.slice(0,240),metadata:{event_id:src.event_id,assignment_id:src.assignment_id,provider:'gmail',attempt_number:src.attempt_number,kind:'team_task_email'},occurred_at:new Date().toISOString()}}];

const src=$('Resolve execution claim').item.json||{};
// Gmail errors are conservatively ambiguous: the provider may have accepted the
// message before the transport failed. Leave the claim in-flight/ambiguous and
// never auto-resend. This prevents duplicate task emails after a crash/timeout.
throw new Error(`VIRYA team email Gmail outcome ambiguous for action ${src.action_id}; manual reconcile required before retry`);

